--!strict
-- Uranium — a reusable dark-theme Roblox UI component library.
--
--   local Uranium = require(path.to.Uranium)
--   local Window  = Uranium:CreateWindow({ Title = "Uranium", Subtitle = "hub", Version = "v1" })
--   local Tab     = Window:CreateTab({ Name = "Home", Icon = "home" })
--   local Group   = Tab:CreateGroup({ Title = "Profile", Column = 1 })
--   Group:Toggle({ Name = "Enable", Default = true, Callback = function(on) end })
--
-- See the component modules under components/ for each control's options.

local Window = __require("components.Window")
local Theme = __require("Theme")
local Asset = __require("util.Asset")
local Log = __require("util.Log")
local Singleton = __require("util.Singleton")

local Uranium = {}

-- Image plumbing, exposed so callers can resolve their own art (ids, https urls,
-- local files) the same way the components do — see util/Asset.lua.
Uranium.Asset = Asset
Uranium.Theme = Theme

-- Point the asset helper at the public art repo, so `Asset.url("x.png")`
-- resolves a bare filename against it. Set here (not in Asset.lua) to keep the
-- brand URL in one place — Theme.Brand.
Asset.Base = Theme.Brand.assets

function Uranium:CreateWindow(options: any?)
	-- A very common miscall is `Uranium.CreateWindow(...)` (dot, not colon) — then
	-- `options` is the table but `self` swallowed nothing, or the caller passes a
	-- bare string title. Catch a non-table here so the failure names the fix
	-- instead of surfacing as a nil-index inside Window.
	if options ~= nil and type(options) ~= "table" then
		Log.fail("CreateWindow", ("options must be a table like { Title = ... }, got %s"
			.. " (did you use Uranium.CreateWindow(...) instead of Uranium:CreateWindow(...)?)")
			:format(typeof(options)))
	end
	return Window(options)
end

-- ── single instance ─────────────────────────────────────────────────────────
-- CreateWindow already unloads whatever a previous run of the loadstring left
-- on screen (util/Singleton.lua), so re-running the loader refreshes the UI
-- instead of stacking a second copy. These expose the same slot to loaders that
-- want to check or clear it themselves:
--
--   if Uranium:IsLoaded() then ... end          -- or getgenv()._URANIUM_LOADED
--   Uranium:Unload()                            -- tear down the live window
Uranium.Singleton = Singleton

function Uranium:IsLoaded(): boolean
	return Singleton.get() ~= nil
end

-- Returns true if a window was actually torn down.
function Uranium:Unload(): boolean
	return Singleton.unloadExisting(Theme.Brand.name)
end

return Uranium

end

__modules['Icons'] = function()
--!strict
-- Icons.lua — name → Lucide vector icon.
--
-- The reference keys icons by short names ("home", "gear", "chev"…). Lucide
-- ships them as solid white glyphs packed into spritesheets; `LucideData.luau`
-- maps each Lucide name to {assetId, {w,h}, {offX,offY}}. We use the "48px"
-- set (plenty for 14–34px UI icons, far lighter than "256px") and translate
-- our short names through ALIAS. Because the glyphs are white on transparent,
-- `ImageColor3` recolors them freely — text_dim for inactive, white for active.

local Create = __require("util.Create")
local Theme = __require("Theme")
local LucideData = __require("LucideData")

local SET = LucideData["48px"]

-- our short name → Lucide name
local ALIAS: { [string]: string } = {
	home   = "home",        cursor = "mouse-pointer",
	input  = "text-cursor-input", list = "list",
	palette = "palette",    layers = "layers",
	bug    = "bug",         person = "user",
	gear   = "settings",    search = "search",
	min    = "minus",       max    = "square",
	close  = "x",           chev   = "chevron-up",
	caret  = "chevron-down", ddchev = "chevron-down",
	check  = "check",       avatar = "circle-user",
	image  = "image",
	-- notify types
	success = "circle-check", info    = "info",
	warning = "triangle-alert", error = "circle-x",
}

-- Unicode fallbacks for any name with no Lucide entry (keeps the UI legible
-- if a name is misspelled or the data file is swapped out).
local GLYPH: { [string]: string } = {
	home = "⌂", layers = "▤", cursor = "➤", input = "⌨", list = "≣",
	palette = "◑", person = "☺", gear = "⚙", search = "⌕", avatar = "☻",
	min = "—", max = "▢", close = "✕", chev = "⌄", caret = "⌄", check = "✓",
	image = "▣",
	success = "✓", info = "ℹ", warning = "⚠", error = "✕",
}

local Icons = {}

local function entryFor(name: string)
	return SET[ALIAS[name] or name]
end

-- Build an icon instance sized `size`, tinted `color`. Returns an ImageLabel
-- when the icon resolves, otherwise a glyph TextLabel fallback.
function Icons.new(name: string, size: number, color: Color3): GuiObject
	local entry = entryFor(name)
	if entry then
		return Create("ImageLabel", {
			Name = "Icon",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(size, size),
			Image = "rbxassetid://" .. entry[1],
			ImageRectSize = Vector2.new(entry[2][1], entry[2][2]),
			ImageRectOffset = Vector2.new(entry[3][1], entry[3][2]),
			ImageColor3 = color,
			ScaleType = Enum.ScaleType.Stretch,
		})
	end
	return Create("TextLabel", {
		Name = "Icon",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(size, size),
		Text = GLYPH[name] or "•",
		TextColor3 = color,
		TextSize = size,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextYAlignment = Enum.TextYAlignment.Center,
	})
end

-- Apply an icon onto an existing ImageLabel/ImageButton (matches the design's
-- `Icons.apply` helper). No-op for unknown names.
function Icons.apply(image: ImageLabel | ImageButton, name: string)
	local entry = entryFor(name)
	if not entry then
		return
	end
	image.Image = "rbxassetid://" .. entry[1]
	image.ImageRectSize = Vector2.new(entry[2][1], entry[2][2])
	image.ImageRectOffset = Vector2.new(entry[3][1], entry[3][2])
end

-- Tint an icon regardless of whether it resolved to an ImageLabel or a glyph.
function Icons.tint(icon: GuiObject, color: Color3)
	if icon:IsA("ImageLabel") or icon:IsA("ImageButton") then
		icon.ImageColor3 = color
	elseif icon:IsA("TextLabel") then
		icon.TextColor3 = color
	end
end

return Icons

end

