__modules['components.Player'] = function()
--!strict
-- components/Player.lua — avatar + name/badge + @username · ID info panel.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Icons = __require("Icons")

return function(ctx: any, opts: any)
	local colors = Theme.Colors

	local panel = Create("Frame", {
		Name = "Player",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.padding(12, 2),
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 14),
		}),
	})

	-- avatar ───────────────────────────────────────────────────────────────
	-- The placeholder tile is accent-*tinted*, with the accent carried by the
	-- icon on top. A 56px solid-accent square was the biggest block of colour
	-- on the Home tab and it wasn't even real content.
	local avatar = Create("Frame", {
		Name = "Avatar",
		Size = UDim2.fromOffset(56, 56),
		BackgroundColor3 = colors.accent_soft,
		ClipsDescendants = true,
		LayoutOrder = 1,
		Parent = panel,
	}, {
		Create.corner(14),
		Create.stroke(colors.border),
	})

	local placeholder: GuiObject? = nil -- Icons.new may resolve to a glyph TextLabel
	if opts.Avatar then
		Create("ImageLabel", {
			Name = "Image",
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			Image = opts.Avatar,
			ScaleType = Enum.ScaleType.Crop,
			Parent = avatar,
		})
	else
		local icon = Icons.new("avatar", 34, colors.accent)
		icon.AnchorPoint = Vector2.new(0.5, 0.5)
		icon.Position = UDim2.fromScale(0.5, 0.5);
		(icon :: any).Parent = avatar
		placeholder = icon
	end

	-- info ─────────────────────────────────────────────────────────────────
	local info = Create("Frame", {
		Name = "Info",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -70, 0, 0), -- fills past the 56px avatar + 14px gap
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Parent = panel,
	}, {
		Create.listLayout({ Padding = UDim.new(0, 2) }),
	})

	local nameRow = Create("Frame", {
		Name = "NameRow",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = info,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 8),
		}),
	})

	Create("TextLabel", {
		Name = "Name",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.XY,
		Text = opts.DisplayName or opts.Username or "Player",
		TextColor3 = colors.text,
		TextSize = 16,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 1,
		Parent = nameRow,
	})

	local badge: TextLabel? = nil
	if opts.Badge then
		-- A filled chip (tinted surface + accent text) rather than an outlined
		-- one: an accent hairline that small reads as a stray line at a glance,
		-- and the fill gives the label something to sit on.
		badge = Create("TextLabel", {
			Name = "Badge",
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(17, 17),
			BackgroundColor3 = colors.accent_soft,
			Text = string.upper(opts.Badge),
			TextColor3 = colors.accent,
			TextSize = 10,
			FontFace = Theme.Font.Bold,
			LayoutOrder = 2,
			Parent = nameRow,
		}, {
			Create.corner(999),
			Create.padding(1, 7),
		})
	end

	local sub = "@" .. (opts.Username or "player")
	if opts.UserId and opts.UserId ~= 0 then
		sub = sub .. "  ·  ID " .. tostring(opts.UserId)
	end
	Create("TextLabel", {
		Name = "Sub",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = sub,
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 2,
		Parent = info,
	})

	ctx:RegisterAccent(function(accent)
		avatar.BackgroundColor3 = ctx.AccentSoft
		if placeholder then
			Icons.tint(placeholder, accent)
		end
		if badge then
			badge.BackgroundColor3 = ctx.AccentSoft
			badge.TextColor3 = accent
		end
	end)

	return panel, {}, false
end

end

__modules['components.PlayerSelect'] = function()
--!strict
-- components/PlayerSelect.lua — single + multi player picker.
-- Same box/popover shell as Dropdown, but the menu lists Players:GetPlayers()
-- live (refetched on every open, and kept in sync while open) with a headshot
-- thumbnail, display name and @username per row. Selection is tracked by UserId
-- so it round-trips through config Flags; :Get() always resolves live against the
-- current player list, so a player who leaves quietly drops out instead of
-- leaving a stale handle.
--
-- The menu SCROLLS: a full server is 30+ players, so the row list lives in a
-- ScrollingFrame capped at MENU_MAX_H. (It used to be a plain auto-sized frame
-- under a UISizeConstraint, which clipped everyone past the sixth player with no
-- way to reach them.)

local Players = game:GetService("Players")

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Field = __require("components.Field")

local MENU_MAX_H = 264 -- popover height cap; rows scroll past it
local MENU_MIN_W = 230
local ROW_H = 40
local TICK_W, AVATAR_W, GAP = 15, 28, 9

-- Headshot URLs are a network round-trip and never change within a session, so
-- they're cached process-wide and in-flight requests are shared. Re-opening the
-- menu (or toggling a row in a multi-select) then reuses the resolved image
-- instead of re-fetching every avatar, which is what made them flicker.
local thumbCache: { [number]: string } = {}
local thumbWaiters: { [number]: { (string) -> () } } = {}

local function requestThumb(userId: number, apply: (string) -> ())
	local cached = thumbCache[userId]
	if cached then
		apply(cached)
		return
	end
	local waiting = thumbWaiters[userId]
	if waiting then
		table.insert(waiting, apply)
		return
	end
	thumbWaiters[userId] = { apply }
	task.spawn(function()
		local ok, content = pcall(
			Players.GetUserThumbnailAsync,
			Players,
			userId,
			Enum.ThumbnailType.HeadShot,
			Enum.ThumbnailSize.Size48x48
		)
		local list = thumbWaiters[userId]
		thumbWaiters[userId] = nil
		if not ok or type(content) ~= "string" or content == "" then
			return
		end
		thumbCache[userId] = content
		for _, fn in list or {} do
			pcall(fn, content)
		end
	end)
end

local function hover(button: GuiButton, base: Color3, over: Color3)
	button.MouseEnter:Connect(function()
		Tween.play(button, Tween.Fast, { BackgroundColor3 = over })
	end)
	button.MouseLeave:Connect(function()
		Tween.play(button, Tween.Fast, { BackgroundColor3 = base })
	end)
end

local function displayName(p: Player): string
	if p.DisplayName ~= "" and p.DisplayName ~= p.Name then
		return p.DisplayName
	end
	return p.Name
end

local function toId(v: any): number?
	if typeof(v) == "Instance" and v:IsA("Player") then
		return v.UserId
	elseif type(v) == "number" then
		return v
	end
	return nil
end

local function build(ctx: any, opts: any, multi: boolean)
	local colors = Theme.Colors
	local placeholder = opts.Placeholder or (multi and "Select players..." or "Select a player...")
	local stack = opts.Stack == true

	local singleId: number? = toId(opts.Default)
	local selected: { [number]: boolean } = {}
	if multi and type(opts.Default) == "table" then
		for _, v in opts.Default do
			local id = toId(v)
			if id then
				selected[id] = true
			end
		end
	end

	local f = Field.new(ctx, opts, stack)

	-- box ────────────────────────────────────────────────────────────────────
	local box = Create("TextButton", {
		Name = "PlayerSelect",
		AutoButtonColor = false,
		Text = "",
		Size = stack and UDim2.new(1, 0, 0, 32) or UDim2.fromOffset(opts.Width or 160, 32),
		BackgroundColor3 = colors.control,
		LayoutOrder = 2,
		Parent = stack and f.field or f.row,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.padding(0, 8, 0, 12),
	})
	local boxStroke = box:FindFirstChildOfClass("UIStroke") :: UIStroke

	local valLabel = Create("TextLabel", {
		Name = "Value",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -24, 1, 0),
		Text = placeholder,
		TextColor3 = colors.text_muted,
		TextSize = 13,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = box,
	})

	local chevron = Icons.new("caret", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0);
	(chevron :: any).Parent = box

	-- menu ─────────────────────────────────────────────────────────────────── (parented to overlay on open)
	-- The CanvasGroup auto-sizes to the scroller, whose height is fitted to the row
	-- list up to MENU_MAX_H (see fitMenu) — past that the canvas overflows and the
	-- list scrolls instead of being silently cut off.
	local menu = Create("CanvasGroup", {
		Name = "PlayerMenu",
		Visible = false,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.fromOffset(MENU_MIN_W, 0),
		BackgroundColor3 = colors.pop,
		ClipsDescendants = true,
	}, {
		Create.corner(8),
		Create.stroke(colors.border),
		Create.padding(5),
	})

	local scroller = Create("ScrollingFrame", {
		Name = "Rows",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = colors.text_dim,
		ScrollBarImageTransparency = 0.35,
		Parent = menu,
	}, {
		Create.listLayout({ Padding = UDim.new(0, 2) }),
	})

	-- The viewport is driven off the layout's measured content height rather than
	-- AutomaticSize, so the menu is exactly as tall as its rows up to MENU_MAX_H
	-- and scrolls beyond it. (The canvas keeps auto-sizing, which is what gives
	-- the overflow something to scroll through.)
	local rowLayout = scroller:FindFirstChildOfClass("UIListLayout") :: UIListLayout
	local function fitMenu()
		scroller.Size = UDim2.new(1, 0, 0, math.min(MENU_MAX_H, rowLayout.AbsoluteContentSize.Y))
	end
	rowLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fitMenu)

	local function selectedPlayers(): { Player }
		local list = {}
		for _, p in Players:GetPlayers() do
			if selected[p.UserId] then
				table.insert(list, p)
			end
		end
		return list
	end

	local function valueLabelText(): (string, boolean)
		if multi then
			local names = {}
			for _, p in selectedPlayers() do
				table.insert(names, displayName(p))
			end
			if #names == 0 then
				return placeholder, false
			end
			return table.concat(names, ", "), true
		else
			local p = singleId and Players:GetPlayerByUserId(singleId)
			if not p then
				return placeholder, false
			end
			return displayName(p), true
		end
	end

	local function relabel()
		local text, hasVal = valueLabelText()
		valLabel.Text = text
		valLabel.TextColor3 = hasVal and colors.text or colors.text_muted
	end

	local function fireCallback()
		if not opts.Callback then
			return
		end
		if multi then
			task.spawn(opts.Callback, selectedPlayers())
		else
			task.spawn(opts.Callback, singleId and Players:GetPlayerByUserId(singleId) or nil)
		end
	end

	local function isSelected(userId: number): boolean
		if multi then
			return selected[userId] == true
		end
		return singleId == userId
	end

	-- Live row handles, keyed by UserId, so picking (or an external :Set) repaints
	-- the affected rows in place instead of tearing the whole menu down — a
	-- rebuild would drop every hover state and restart the open animation.
	type Row = { tick: GuiObject, name: TextLabel }
	local rows: { [number]: Row } = {}

	local function paintRow(userId: number)
		local row = rows[userId]
		if not row then
			return
		end
		local sel = isSelected(userId)
		row.tick.Visible = sel
		row.name.TextColor3 = sel and colors.text or colors.text_muted
	end

	local function repaintAll()
		for userId in rows do
			paintRow(userId)
		end
	end

	local function pick(p: Player)
		if multi then
			local was = selected[p.UserId] == true
			selected[p.UserId] = (not was) or nil
			paintRow(p.UserId)
			relabel()
		else
			local previous = singleId
			singleId = p.UserId
			if previous then
				paintRow(previous)
			end
			paintRow(p.UserId)
			relabel()
			ctx:ClosePopover()
		end
		fireCallback()
	end

	local function rebuild()
		table.clear(rows)
		for _, child in scroller:GetChildren() do
			if child:IsA("GuiButton") or child:IsA("TextLabel") then
				child:Destroy()
			end
		end

		local players = Players:GetPlayers()
		table.sort(players, function(a, b)
			return displayName(a):lower() < displayName(b):lower()
		end)

		if #players == 0 then
			Create("TextLabel", {
				Name = "Empty",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 28),
				Text = "No players online",
				TextColor3 = colors.text_muted,
				TextSize = 13,
				FontFace = Theme.Font.Regular,
				Parent = scroller,
			})
			return
		end

		for i, p in players do
			local userId = p.UserId

			local row = Create("TextButton", {
				Name = tostring(userId),
				AutoButtonColor = false,
				Text = "",
				BackgroundColor3 = colors.control_hi,
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -4, 0, ROW_H), -- -4 keeps rows clear of the scrollbar
				LayoutOrder = i,
				ClipsDescendants = true,
				Parent = scroller,
			}, {
				Create.corner(6),
				Create.padding(0, 8),
				Create.listLayout({
					FillDirection = Enum.FillDirection.Horizontal,
					VerticalAlignment = Enum.VerticalAlignment.Center,
					Padding = UDim.new(0, GAP),
				}),
			})

			local tickHolder = Create("Frame", {
				Name = "Tick",
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(TICK_W, TICK_W),
				LayoutOrder = 1,
				Parent = row,
			})
			local tick = Icons.new("check", 14, ctx.Accent)
			tick.Visible = false;
			(tick :: any).Parent = tickHolder

			-- avatar: accent-tinted placeholder with a generic icon, swapped for the
			-- real headshot once the (cached) thumbnail lookup resolves — the fetch
			-- runs off-thread so opening the menu never blocks on the network.
			local avatar = Create("Frame", {
				Name = "Avatar",
				Size = UDim2.fromOffset(AVATAR_W, AVATAR_W),
				BackgroundColor3 = ctx.AccentSoft,
				ClipsDescendants = true,
				LayoutOrder = 2,
				Parent = row,
			}, {
				Create.corner(8),
			})
			local avatarIcon = Icons.new("avatar", 16, ctx.Accent)
			avatarIcon.AnchorPoint = Vector2.new(0.5, 0.5)
			avatarIcon.Position = UDim2.fromScale(0.5, 0.5);
			(avatarIcon :: any).Parent = avatar

			requestThumb(userId, function(image)
				if not avatar.Parent then
					return
				end
				avatarIcon.Visible = false
				local existing = avatar:FindFirstChild("Image")
				if existing and existing:IsA("ImageLabel") then
					existing.Image = image
					return
				end
				Create("ImageLabel", {
					Name = "Image",
					BackgroundTransparency = 1,
					Size = UDim2.fromScale(1, 1),
					Image = image,
					Parent = avatar,
				})
			end)

			-- Names take the row's leftover width (offset-sized, truncated) so a long
			-- display name can't push the @username past the menu edge.
			local names = Create("Frame", {
				Name = "Names",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -(TICK_W + AVATAR_W + GAP * 2), 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				LayoutOrder = 3,
				Parent = row,
			}, {
				Create.listLayout({ Padding = UDim.new(0, 1) }),
			})

			local nameLabel = Create("TextLabel", {
				Name = "Display",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 15),
				Text = displayName(p),
				TextColor3 = colors.text_muted,
				TextSize = 13,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				LayoutOrder = 1,
				Parent = names,
			})
			Create("TextLabel", {
				Name = "Username",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 13),
				Text = "@" .. p.Name,
				TextColor3 = colors.text_dim,
				TextSize = 11,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				LayoutOrder = 2,
				Parent = names,
			})

			rows[userId] = { tick = tick, name = nameLabel }
			paintRow(userId)

			row.MouseEnter:Connect(function()
				Tween.play(row, Tween.Fast, { BackgroundTransparency = 0 })
			end)
			row.MouseLeave:Connect(function()
				Tween.play(row, Tween.Fast, { BackgroundTransparency = 1 })
			end)
			row.Activated:Connect(function()
				pick(p)
			end)
		end
	end

	local function setOpenVisual(open: boolean)
		Tween.play(boxStroke, Tween.Fast, { Color = open and ctx.Accent or colors.border })
		Tween.play(chevron, Tween.Spin, { Rotation = open and 180 or 0 })
	end

	-- Roster changes while the menu is open rebuild it, so someone joining or
	-- leaving mid-pick doesn't leave a row pointing at a player who's gone.
	local liveConns: { RBXScriptConnection } = {}
	local function stopWatching()
		for _, conn in liveConns do
			conn:Disconnect()
		end
		table.clear(liveConns)
	end

	box.Activated:Connect(function()
		if ctx:IsOpen(menu) then
			ctx:ClosePopover()
			return
		end
		rebuild()
		fitMenu()
		scroller.CanvasPosition = Vector2.new(0, 0)
		menu.Size = UDim2.fromOffset(math.max(box.AbsoluteSize.X, MENU_MIN_W), 0)
		setOpenVisual(true)
		table.insert(liveConns, Players.PlayerAdded:Connect(rebuild))
		table.insert(liveConns, Players.PlayerRemoving:Connect(function()
			-- PlayerRemoving fires before the player leaves GetPlayers(), so rebuild
			-- on the next step to get the post-departure roster.
			task.defer(function()
				if ctx:IsOpen(menu) then
					rebuild()
				end
			end)
		end))
		ctx:OpenPopover(menu, box, function()
			stopWatching()
			setOpenVisual(false)
		end)
	end)
	hover(box, colors.control, colors.control_hi)

	-- The box label resolves UserIds to live players, so it has to be redrawn when
	-- someone selected leaves (or rejoins) — otherwise it keeps naming a player
	-- who isn't in the server any more. Self-disconnects once the control is gone,
	-- since these signals outlive the ScreenGui.
	do
		local rosterConns: { RBXScriptConnection } = {}
		local function onRoster(p: Player)
			if not box:IsDescendantOf(game) then
				for _, conn in rosterConns do
					conn:Disconnect()
				end
				table.clear(rosterConns)
				return
			end
			if isSelected(p.UserId) then
				task.defer(relabel)
			end
		end
		table.insert(rosterConns, Players.PlayerRemoving:Connect(onRoster))
		table.insert(rosterConns, Players.PlayerAdded:Connect(onRoster))
	end

	relabel()

	local handle = {}
	function handle:Get(): any
		if multi then
			return selectedPlayers()
		end
		return singleId and Players:GetPlayerByUserId(singleId) or nil
	end
	function handle:Set(value: any)
		if multi then
			table.clear(selected)
			if type(value) == "table" then
				for _, v in value do
					local id = toId(v)
					if id then
						selected[id] = true
					end
				end
			end
		else
			singleId = toId(value)
		end
		relabel()
		repaintAll()
		fireCallback()
	end

	return f.field, handle, true
end

return build

end

__modules['components.Section'] = function()
--!strict
-- components/Section.lua — a nested collapsible group (indented, left rule).
-- Returns the section frame plus the inner body that controls mount into.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Collapse = __require("util.Collapse")

return function(ctx: any, opts: any): (Frame, Frame)
	local colors = Theme.Colors
	local collapsed = opts.Collapsed == true

	local section = Create("Frame", {
		Name = "Section",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.listLayout({}),
	})

	-- No UIListLayout on the header: a layout-managed child won't render its
	-- Rotation, so the chevron is positioned manually to keep it free to spin.
	local head = Create("TextButton", {
		Name = "Head",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = section,
	}, {
		Create.padding(9, 2),
	})

	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -18, 0, 0), -- leaves room for the chevron flush right
		Text = opts.Title or "Section",
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = head,
	})

	local chevron = Icons.new("chev", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0)
	chevron.Rotation = collapsed and 180 or 0;
	(chevron :: any).Parent = head

	local bodyWrap = Create("Frame", {
		Name = "BodyWrap",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	})

	local body = Create("Frame", {
		Name = "Body",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(14, 0),
		Size = UDim2.new(1, -14, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = bodyWrap,
	}, {
		Create.padding(1, 0, 8, 0),
		Create.listLayout({}),
	})

	-- Left rule. Scale height (1,0 on Y) fills bodyWrap natively; scale-sized
	-- children are ignored by AutomaticSize, so the rule can't feed back into
	-- bodyWrap's height and cause AbsoluteSizeChanged re-entrancy.
	Create("Frame", {
		Name = "Rule",
		Position = UDim2.fromOffset(2, 1),
		Size = UDim2.new(0, 1, 1, 0),
		BackgroundColor3 = colors.border,
		BorderSizePixel = 0,
		Parent = bodyWrap,
	})

	-- Clipping holder owns the body's height so it slides open/closed.
	local holder, setCollapsed = Collapse.wrap(bodyWrap, collapsed)
	holder.LayoutOrder = 2
	holder.Parent = section

	head.Activated:Connect(function()
		collapsed = not collapsed
		Tween.play(chevron, Tween.Spin, { Rotation = collapsed and 180 or 0 })
		setCollapsed(collapsed, true)
	end)

	return section, body
end

end

__modules['components.Slider'] = function()
--!strict
-- components/Slider.lua — 6px pill track, accent fill, 15px white knob.
-- Live drag via UserInputService (no tween), clamped + stepped.

local UserInputService = game:GetService("UserInputService")

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Log = __require("util.Log")
local Field = __require("components.Field")

local function clamp(v: number, a: number, b: number): number
	return math.max(a, math.min(b, v))
end

local function format(v: number, suffix: string): string
	return ("%g"):format(v) .. suffix
end

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local where = Log.where("Slider", opts.Name)
	Log.field(where, "Min", opts.Min, "number")
	Log.field(where, "Max", opts.Max, "number")
	Log.field(where, "Step", opts.Step, "number")

	local min = opts.Min or 0
	local max = opts.Max or 100
	-- An inverted or collapsed range makes every position map to the same value
	-- (render()/snap() guard the maths, but the control would be dead). Warn and
	-- fall back to a sane [min, min+1] so it's at least usable.
	if min >= max then
		Log.warn(where, ("Min (%s) must be less than Max (%s) — using [%s, %s]."):format(
			("%g"):format(min), ("%g"):format(max), ("%g"):format(min), ("%g"):format(min + 1)))
		max = min + 1
	end
	local step = opts.Step or 1
	if step < 0 then
		Log.warn(where, ("Step (%s) can't be negative — using 1."):format(("%g"):format(step)))
		step = 1
	end
	local suffix = opts.Suffix or ""
	local value = clamp(opts.Default or min, min, max)

	local f = Field.new(ctx, opts, true)

	local valBox = Create("TextLabel", {
		Name = "Value",
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.fromOffset(38, 22),
		BackgroundColor3 = colors.control,
		Text = format(value, suffix),
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Medium,
		LayoutOrder = 2,
		Parent = f.row,
	}, {
		Create.corner(6),
		Create.stroke(colors.border),
		Create.padding(2, 9),
		Create("UISizeConstraint", { MinSize = Vector2.new(38, 22) }),
	})

	-- The grab area is 18px tall and transparent; the visible 6px rail is centered
	-- inside it. A 6px-tall button is a genuinely hard target to hit with a mouse
	-- (and near-impossible on touch), which is what made the slider feel broken.
	local track = Create("TextButton", {
		Name = "Slider",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		LayoutOrder = 2,
		Parent = f.field,
	})

	local rail = Create("Frame", {
		Name = "Rail",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.new(1, 0, 0, 6),
		BackgroundColor3 = colors.toggle_off,
		Parent = track,
	}, {
		Create.corner(999),
	})

	local fill = Create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = ctx.Accent,
		Parent = rail,
	}, {
		Create.corner(999),
	})

	local knob = Create("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(15, 15),
		-- Text (not knockout): at value 0 the knob sits off the accent fill, on
		-- the bare rail, where a knockout-dark knob would disappear.
		BackgroundColor3 = colors.text,
		ZIndex = 2,
		Parent = rail,
	}, {
		Create.corner(999),
		Create("UIScale", {}),
	})
	local knobScale = knob:FindFirstChildOfClass("UIScale") :: UIScale

	local function snap(v: number): number
		-- guard a zero step so a bad config can't divide-by-zero. (Explicit if,
		-- not `and/or` — the snapped value can legitimately be 0, which the idiom
		-- would mistake for false and fall through to v.)
		if step > 0 then
			return math.round(v / step) * step
		end
		return v
	end

	local function render()
		-- guard min==max (degenerate range) so the ratio never produces NaN
		local span = max - min
		local pct = span ~= 0 and (value - min) / span or 0
		fill.Size = UDim2.fromScale(pct, 1)
		knob.Position = UDim2.fromScale(pct, 0.5)
		valBox.Text = format(value, suffix)
	end

	local function setFromX(x: number)
		local span = rail.AbsoluteSize.X
		local pct = span > 0 and clamp((x - rail.AbsolutePosition.X) / span, 0, 1) or 0
		value = clamp(snap(min + pct * (max - min)), min, max)
		render()
		if opts.Callback then
			task.spawn(opts.Callback, value)
		end
	end

	-- The move/release listeners are global (UserInputService), so they're only
	-- connected for the duration of a drag and torn down on release. That avoids
	-- N idle sliders each leaking a permanent listener that fires on every mouse
	-- move and survives Window:Destroy.
	local dragConns: { RBXScriptConnection } = {}
	local function endDrag()
		for _, c in dragConns do
			c:Disconnect()
		end
		table.clear(dragConns)
		Tween.play(knobScale, Tween.Spring, { Scale = 1 }) -- settle back on release
	end
	track.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			if #dragConns > 0 then
				return
			end
			Tween.play(knobScale, Tween.Spring, { Scale = 1.3 }) -- grow while grabbed
			setFromX(input.Position.X)
			table.insert(dragConns, UserInputService.InputChanged:Connect(function(move)
				if move.UserInputType == Enum.UserInputType.MouseMovement
					or move.UserInputType == Enum.UserInputType.Touch then
					setFromX(move.Position.X)
				end
			end))
			table.insert(dragConns, UserInputService.InputEnded:Connect(function(up)
				if up.UserInputType == Enum.UserInputType.MouseButton1
					or up.UserInputType == Enum.UserInputType.Touch then
					endDrag()
				end
			end))
		end
	end)

	ctx:RegisterAccent(function(accent)
		fill.BackgroundColor3 = accent
	end)
	render()

	local handle = {}
	function handle:Get(): number
		return value
	end
	function handle:Set(v: number)
		value = clamp(snap(v), min, max)
		render()
		if opts.Callback then
			task.spawn(opts.Callback, value)
		end
	end

	return f.field, handle, true
end

end

__modules['components.Tab'] = function()
--!strict
-- components/Tab.lua — a sidebar nav button + a two-column content page.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Log = __require("util.Log")
local Group = __require("components.Group")

local M = Theme.Metrics

local function newColumn(order: number): Frame
	return Create("Frame", {
		Name = "Column",
		BackgroundTransparency = 1,
		AnchorPoint = order == 2 and Vector2.new(1, 0) or Vector2.new(0, 0),
		Position = order == 2 and UDim2.fromScale(1, 0) or UDim2.fromScale(0, 0),
		Size = UDim2.new(0.5, -(M.columnGap / 2), 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.listLayout({ Padding = UDim.new(0, M.groupGap) }),
	})
end

return function(ctx: any, opts: any)
	local colors = Theme.Colors

	-- nav button ──────────────────────────────────────────────────────────
	local button = Create("TextButton", {
		Name = "Nav_" .. (opts.Name or "Tab"),
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(M.navButton, M.navButton),
		BackgroundColor3 = colors.accent_soft,
		BackgroundTransparency = 1,
	}, {
		Create.corner(M.navRadius),
	})

	-- No glow behind the active button: the Uranium palette is flat fills only.
	-- The active state is a *tinted* tile (accent_soft) with an accent icon on
	-- it, plus the rail below — a solid accent tile put a neon block in the
	-- sidebar of every screenshot, and it fought the primary button for the eye.
	--
	-- The rail is the loud half of the active state, and it can afford to be:
	-- it's 3×18px. It lives in the sidebar gutter left of the button (the nav
	-- frame doesn't clip), and grows out of nothing on select.
	local rail = Create("Frame", {
		Name = "Rail",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, -9, 0.5, 0),
		Size = UDim2.fromOffset(3, 0),
		BackgroundColor3 = colors.accent,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Parent = button,
	}, {
		Create.corner(999),
	})

	local icon = Icons.new(opts.Icon or "gear", M.navIcon, colors.text_dim)
	icon.AnchorPoint = Vector2.new(0.5, 0.5)
	icon.Position = UDim2.fromScale(0.5, 0.5);
	(icon :: any).Parent = button
	local iconScale = Create("UIScale", { Parent = icon })

	-- content page ────────────────────────────────────────────────────────
	local page = Create("Frame", {
		Name = "Page_" .. (opts.Name or "Tab"),
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
	})
	local columns = Create("Frame", {
		Name = "Columns",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = page,
	})
	local col1 = newColumn(1)
	col1.Parent = columns
	local col2 = newColumn(2)
	col2.Parent = columns

	-- Scale height (1,0 on Y) so the divider fills the column block natively.
	-- Roblox excludes scale-sized children from a parent's AutomaticSize, so this
	-- can't feed back into `columns` and trigger AbsoluteSizeChanged re-entrancy
	-- (the old signal-driven offset height oscillated on subpixel rounding).
	Create("Frame", {
		Name = "ColDivider",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0),
		Size = UDim2.new(0, 1, 1, 0),
		BackgroundColor3 = colors.border_soft,
		BorderSizePixel = 0,
		Parent = columns,
	})

	-- nav state ──────────────────────────────────────────────────────────
	local active = false
	local hovering = false
	-- Crossfade both colour and transparency in a single tween. The old code
	-- snapped BackgroundColor3 to white instantly while the fill was still
	-- opaque (and snapped transparency to 0 on activate), so a switched-off tab
	-- showed a solid flash for one frame before fading. Idle keeps the *tint*
	-- colour and only fades the transparency, so there's no intermediate solid
	-- colour to flash — the tile simply fades in / out.
	local function paint(animate: boolean?)
		local goal, railGoal
		rail.BackgroundColor3 = ctx.Accent
		if active then
			goal = { BackgroundColor3 = ctx.AccentSoft, BackgroundTransparency = 0 }
			Icons.tint(icon, ctx.Accent) -- the icon carries the colour, not the tile
			railGoal = { Size = UDim2.fromOffset(3, 18), BackgroundTransparency = 0 }
		else
			goal = {
				-- idle (transparency 1) keeps the tint colour so the fade-out is a
				-- pure fade; hover is one step lighter than the chrome.
				BackgroundColor3 = hovering and colors.control_hi or ctx.AccentSoft,
				BackgroundTransparency = hovering and 0 or 1,
			}
			Icons.tint(icon, hovering and colors.text_muted or colors.text_dim)
			railGoal = { Size = UDim2.fromOffset(3, 0), BackgroundTransparency = 1 }
		end
		if animate == false then
			for key, value in goal do
				(button :: any)[key] = value
			end
			for key, value in railGoal do
				(rail :: any)[key] = value
			end
		else
			Tween.play(button, Tween.Fast, goal)
			-- Overshoot on the way in only: Back easing on the way *out* would
			-- pull the height below zero before settling.
			Tween.play(rail, active and Tween.Spring or Tween.Fast, railGoal)
		end
	end
	button.MouseEnter:Connect(function()
		hovering = true
		if not active then
			paint()
		end
	end)
	button.MouseLeave:Connect(function()
		hovering = false
		if not active then
			paint()
		end
	end)
	ctx:RegisterAccent(function()
		rail.BackgroundColor3 = ctx.Accent
		if active then
			button.BackgroundColor3 = ctx.AccentSoft
			Icons.tint(icon, ctx.Accent)
		end
	end)

	local tab = {
		button = button,
		page = page,
	}

	-- The page's resting position is captured once, on first activation (Window
	-- sets it before selecting the first tab). Re-reading page.Position on every
	-- activation meant a fast tab switch sampled a mid-tween value and adopted it
	-- as "rest", so the page crept further down the screen with each switch.
	local restPos: UDim2? = nil
	local slideTween: Tween? = nil

	function tab:_setActive(value: boolean)
		local becameActive = value and not active
		active = value
		page.Visible = value
		paint()
		if becameActive then
			iconScale.Scale = 0.8
			Tween.play(iconScale, Tween.Spring, { Scale = 1 }) -- pop on select
			-- ease the page up into place so switching tabs settles instead of
			-- hard-cutting (rest position is set by Window; nudge down, slide back)
			local rest = restPos or page.Position
			restPos = rest
			if slideTween then
				slideTween:Cancel()
			end
			page.Position = rest + UDim2.fromOffset(0, 10)
			slideTween = Tween.play(page, Tween.Normal, { Position = rest })
		end
	end
	function tab:CreateGroup(groupOpts: any)
		if groupOpts ~= nil and type(groupOpts) ~= "table" then
			Log.fail("CreateGroup", ("options must be a table like { Title = ..., Column = 1 }, got %s")
				:format(typeof(groupOpts)))
		end
		-- Column is 1 (left) or 2 (right). A stray value (e.g. Column = 3, or a
		-- string) would silently land the group in the left column — warn and
		-- fall back so the author knows their column choice was ignored.
		local column = groupOpts and groupOpts.Column
		if column ~= nil and column ~= 1 and column ~= 2 then
			Log.warn(Log.where("CreateGroup", groupOpts and groupOpts.Title),
				("Column must be 1 (left) or 2 (right), got %s — using column 1."):format(tostring(column)))
		end
		local target = (column == 2) and col2 or col1
		return Group(ctx, target, groupOpts or {})
	end

	return tab
end

end

__modules['components.Toggle'] = function()
--!strict
-- components/Toggle.lua — 42×23 pill, 17px knob, +19px travel.
--
-- Optionally carries a keybind chip in the same row (`Keybind` /
-- `KeybindMode`), so "hold B for walkspeed" is one option on the control rather
-- than a second control wired up by hand. The chip owns a binding in
-- util/Bind.lua; the toggle's value stays the single source of truth, which is
-- why Toggle mode asks for it via `GetState` instead of tracking its own.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Log = __require("util.Log")
local Field = __require("components.Field")
local BindChip = __require("components.BindChip")

local OFF_POS = UDim2.fromOffset(3, 3)
local ON_POS = UDim2.fromOffset(22, 3) -- 3 + 19px travel

return function(ctx: any, opts: any)
	opts = opts or {}
	local colors = Theme.Colors
	local where = Log.where("Toggle", opts.Name)
	Log.field(where, "Keybind", opts.Keybind, "EnumItem")
	Log.field(where, "KeybindMode", opts.KeybindMode, "string")
	Log.field(where, "KeybindModes", opts.KeybindModes, "table")
	Log.field(where, "KeybindFlag", opts.KeybindFlag, "string")

	local f = Field.new(ctx, opts)
	local state = opts.Default == true

	local track = Create("TextButton", {
		Name = "Toggle",
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(42, 23),
		BackgroundColor3 = colors.toggle_off,
		LayoutOrder = 3,
		Parent = f.row,
	}, {
		Create.corner(999),
	})

	local knob = Create("Frame", {
		Name = "Knob",
		Size = UDim2.fromOffset(17, 17),
		Position = OFF_POS,
		BackgroundColor3 = colors.knob,
		Parent = track,
	}, {
		Create.corner(999),
	})

	local function paint(animate: boolean)
		local trackColor = state and ctx.Accent or colors.toggle_off
		-- on = knockout knob on the accent track, off = text-faint knob on surface
		local knobColor = state and colors.knockout or colors.knob
		local pos = state and ON_POS or OFF_POS
		if animate then
			Tween.play(track, Tween.Normal, { BackgroundColor3 = trackColor })
			Tween.play(knob, Tween.Normal, { BackgroundColor3 = knobColor })
			Tween.play(knob, Tween.Spring, { Position = pos }) -- slight overshoot on the slide
		else
			track.BackgroundColor3 = trackColor
			knob.BackgroundColor3 = knobColor
			knob.Position = pos
		end
	end

	local bind: any = nil

	local handle = {}
	function handle:Get(): boolean
		return state
	end
	function handle:Set(value: boolean)
		state = value == true
		paint(true)
		-- Keep the chip's idea of the value in step (so a Hold chip un-lights, and
		-- a Toggle press after a manual click flips the right way) without letting
		-- it re-enter the callback.
		if bind then
			bind:SetState(state)
		end
		if opts.Callback then
			task.spawn(opts.Callback, state)
		end
	end

	track.Activated:Connect(function()
		handle:Set(not state)
	end)

	-- ── optional keybind ─────────────────────────────────────────────────────
	if opts.Keybind ~= nil or opts.KeybindMode ~= nil then
		local chip, chipHandle = BindChip(ctx, {
			Key = opts.Keybind,
			Mode = opts.KeybindMode or "Toggle",
			Modes = opts.KeybindModes,
			Default = state,
			Compact = true,
			LayoutOrder = 2,
			Where = where,
			GetState = function()
				return state
			end,
			OnActivate = function(active)
				handle:Set(active)
			end,
		})
		chip.Parent = f.row
		bind = chipHandle
		handle.Bind = chipHandle
		-- The key + mode persist separately from the toggle's own value, so a saved
		-- config restores "hold B" as well as "on".
		if opts.KeybindFlag then
			ctx:RegisterFlag(opts.KeybindFlag, chipHandle, "bind")
		end
	end

	ctx:RegisterAccent(function()
		paint(false)
	end)

	return f.field, handle, true
end

end

__modules['components.Window'] = function()
--!strict
-- components/Window.lua — the window shell: titlebar, sidebar, scrolling content,
-- status bar and overlay. Owns the Context, the tab list, notifications and the
-- live accent. Mounts a ScreenGui to the LocalPlayer's PlayerGui.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Context = __require("util.Context")
local Bind = __require("util.Bind")
local Config = __require("util.Config")
local Asset = __require("util.Asset")
local Log = __require("util.Log")
local Singleton = __require("util.Singleton")
local Tab = __require("components.Tab")
local Notify = __require("components.Notify")

local M = Theme.Metrics

return function(opts: any)
	opts = opts or {}
	local colors = Theme.Colors

	-- Validate the window options up front so a wrong type surfaces here (naming
	-- the field) rather than as a mystery error much later when it's first used.
	Log.field("CreateWindow", "Title", opts.Title, "string")
	Log.field("CreateWindow", "ToggleKey", opts.ToggleKey, "EnumItem")
	Log.field("CreateWindow", "Accent", opts.Accent, "Color3")
	Log.field("CreateWindow", "ConfigFolder", opts.ConfigFolder, "string")
	Log.field("CreateWindow", "LogoRadius", opts.LogoRadius, "number")
	Log.field("CreateWindow", "LogoZoom", opts.LogoZoom, "number")
	Log.field("CreateWindow", "AllowMultiple", opts.AllowMultiple, "boolean")

	-- where configs are saved on disk + which key shows/hides the window
	local configFolder = opts.ConfigFolder or "uranium"
	local toggleKey: Enum.KeyCode = opts.ToggleKey or Enum.KeyCode.RightShift
	local notificationsEnabled = true
	-- UserInputService connections live past the ScreenGui's lifetime, so they're
	-- tracked here and disconnected by Window:Destroy.
	local connections: { RBXScriptConnection } = {}

	-- ── single instance ───────────────────────────────────────────────────────
	-- Only one Uranium on screen at a time: re-running the loadstring unloads the
	-- window the previous run left behind (util/Singleton.lua — the handle lives
	-- on getgenv()._URANIUM_LOADED so it survives across chunks), then builds
	-- fresh below. That way the loader refreshes the UI instead of stacking a
	-- second copy over the first. `AllowMultiple = true` opts out of both halves.
	local singleton = opts.AllowMultiple ~= true
	local record: any = nil
	if singleton and Singleton.unloadExisting(Theme.Brand.name) then
		print("[Uranium] already loaded — unloaded the previous window and refreshing.")
	end

	-- ── ScreenGui + window frame ────────────────────────────────────────────
	local screenGui = Create("ScreenGui", {
		Name = Theme.Brand.name,
		IgnoreGuiInset = true,
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})

	-- CanvasGroup (not Frame) so minimize/close can fade the *entire* window as a
	-- single unit via GroupTransparency — a plain Frame can only fade its own
	-- background, which is why scaling-then-hiding looked like a snap.
	local main = Create("CanvasGroup", {
		Name = "Window",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(M.windowWidth, M.windowHeight),
		BackgroundColor3 = colors.bg,
		ClipsDescendants = true,
		Parent = screenGui,
	}, {
		Create.corner(M.windowRadius),
		Create.stroke(Color3.new(0, 0, 0)),
		Create("UIScale", {}),
	})
	local mainScale = main:FindFirstChildOfClass("UIScale") :: UIScale

	-- ── drop shadow ─────────────────────────────────────────────────────────
	-- The reference window floats: `box-shadow: 0 30px 80px -20px rgba(0,0,0,.8)`.
	-- A 9-sliced soft-shadow image behind the window gives it that elevation. It
	-- lives in the ScreenGui (a sibling behind `main`, not a child — `main`
	-- clips, and the shadow has to bleed past the window edges) and tracks the
	-- window as it's dragged / resized.
	-- A *radial* shadow image (one smooth centre→edge gradient) stretched behind
	-- the window. A 9-slice shadow only softens its ~49px border and stretches a
	-- solid core, so it reads as a hard dark band that ends abruptly — this fades
	-- gradually the whole way out instead. Big PAD = the gradient's soft tail is
	-- what shows past the window edge; the dark middle stays hidden behind it.
	local SHADOW_PAD = 60 -- how far the soft tail bleeds past each edge (bigger = more gradual falloff)
	local SHADOW_DROP = 8  -- nudge down so the light reads as coming from above (kept small so the bottom doesn't read heavy)
	local SHADOW_T = 0.82  -- resting image transparency (high = faint, barely-there shadow)
	local shadow = Create("ImageLabel", {
		Name = "Shadow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = main.Position,
		Size = UDim2.fromOffset(M.windowWidth + SHADOW_PAD, M.windowHeight + SHADOW_PAD),
		BackgroundTransparency = 1,
		Image = "rbxassetid://1316045217", -- soft radial blur
		ImageColor3 = Color3.new(0, 0, 0),
		ImageTransparency = 1, -- faded in on mount, alongside the window
		ScaleType = Enum.ScaleType.Stretch,
		ZIndex = 0,
		Parent = screenGui,
	})
	local function syncShadow()
		shadow.Position = main.Position + UDim2.fromOffset(0, SHADOW_DROP)
		shadow.Size = UDim2.new(
			main.Size.X.Scale, main.Size.X.Offset + SHADOW_PAD,
			main.Size.Y.Scale, main.Size.Y.Offset + SHADOW_PAD
		)
	end
	main:GetPropertyChangedSignal("Position"):Connect(syncShadow)
	main:GetPropertyChangedSignal("Size"):Connect(syncShadow)

	-- Never exceed the viewport — on small screens the window shrinks to fit
	-- (centered) instead of spilling content off the right/bottom edge. Skipped
	-- while maximized, which owns the size itself (this used to fight it and snap
	-- a maximized window back to its default size on any viewport change).
	local maximized = false
	local function fitWindow()
		local vp = screenGui.AbsoluteSize
		if vp.X <= 0 then
			return
		end
		if maximized then
			main.Size = UDim2.fromOffset(
				math.max(M.windowWidth, vp.X - 24),
				math.max(M.windowHeight, vp.Y - 24)
			)
			return
		end
		main.Size = UDim2.fromOffset(
			math.min(M.windowWidth, vp.X - 24),
			math.min(M.windowHeight, vp.Y - 24)
		)
	end
	screenGui:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitWindow)
	task.defer(fitWindow)

	-- ── titlebar ───────────────────────────────────────────────────────────
	local titlebar = Create("Frame", {
		Name = "Titlebar",
		Size = UDim2.new(1, 0, 0, M.titlebar),
		BackgroundColor3 = colors.chrome,
		Parent = main,
	}, {
		-- Round the top corners to match the window. main's ClipsDescendants
		-- clips to a rectangle (not the rounded shape), so without this the
		-- square chrome corners poke past main's rounded corners.
		Create.corner(M.windowRadius),
		Create("Frame", { -- square off the bottom so only the top corners round
			Name = "SquareFill",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, M.windowRadius),
			BackgroundColor3 = colors.chrome,
			BorderSizePixel = 0,
		}),
		Create("Frame", { -- bottom hairline
			Name = "Border",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, 1),
			BackgroundColor3 = colors.border_soft,
			BorderSizePixel = 0,
		}),
	})

	-- logo — the brand mark, square art rounded off by the holder's UICorner.
	-- `Logo` accepts anything util/Asset.lua resolves (id, url, file path); the
	-- accent square with the brand initial is the fallback while it loads or if
	-- it never resolves (Studio without executor globals, bad id, …).
	local logo = Create("Frame", {
		Name = "Logo",
		Size = UDim2.fromOffset(M.logo, M.logo),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, M.sidebar / 2, 0.5, 0),
		BackgroundColor3 = colors.accent,
		ClipsDescendants = true,
		Parent = titlebar,
	}, {
		Create.corner(opts.LogoRadius or Theme.Brand.radius),
	})
	local brandName = opts.Title or Theme.Brand.name
	local logoFallback = Create("TextLabel", {
		Name = "Initial",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Text = brandName:sub(1, 1):upper(),
		TextColor3 = colors.knockout,
		TextSize = 17,
		FontFace = Theme.Font.Bold,
		Parent = logo,
	})
	-- Fit, not Crop: a brand mark must never lose an edge or change proportion.
	-- Fit letterboxes non-square art inside the square holder; the zoom below is
	-- what fills the holder, and it's a scale on both axes so it can't stretch.
	local logoImage = Create("ImageLabel", {
		Name = "Mark",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1, 1),
		Image = "",
		ScaleType = Enum.ScaleType.Fit,
		Visible = false,
		Parent = logo,
	}) :: ImageLabel
	-- `zoom` > 1 draws the art oversized inside the clipping holder, trimming a
	-- margin baked into the source (see Theme.Brand.zoom). nil = draw it 1:1.
	local function setLogo(source: any, zoom: number?)
		local z = tonumber(zoom) or 1
		if z <= 0 then
			z = 1
		end
		logoImage.Size = UDim2.fromScale(z, z)
		-- The mark is ALWAYS visible — it has to be, or the engine never fetches
		-- the texture — and it's drawn over the accent square, which stays put as
		-- a backdrop. So the art covers the square when it loads, and if it never
		-- loads you're left with the accent square + initial. Never a hole,
		-- whatever the load check believes.
		logoImage.Visible = true
		logoFallback.Visible = true
		logo.BackgroundTransparency = 0
		Asset.load(logoImage, source, function(loaded)
			-- Only the fallback reacts; the image is left alone.
			logoFallback.Visible = not loaded
			logo.BackgroundTransparency = loaded and 1 or 0
			if not loaded and source ~= nil then
				Log.warn("CreateWindow", ("Logo %s hasn't loaded — the fallback mark is showing. "
					.. "Check the id is an image/decal, that it passed moderation, and that "
					.. "it isn't Restricted in Creator Dashboard."):format(tostring(source)))
			end
		end)
	end
	-- `Logo = false` means "no art at all" — keep the accent square + initial.
	-- The built-in mark gets Theme.Brand.zoom (its margin is known); art the
	-- caller supplied is drawn 1:1 unless they ask for a zoom themselves.
	if opts.Logo == false then
		setLogo(nil)
	elseif opts.Logo ~= nil then
		setLogo(opts.Logo, opts.LogoZoom)
	else
		setLogo(Theme.Brand.logo, opts.LogoZoom or Theme.Brand.zoom)
	end

	-- Wordmark: uppercase with wide letter-spacing. Roblox has no tracking /
	-- letter-spacing property on TextLabel, so the spacing is literal — a space
	-- between every glyph. A word break becomes three spaces, which still reads
	-- as a wordmark. Short brand names only; that's what a titlebar title is.
	local function wordmark(s: string): string
		local out = {}
		for _, c in utf8.codes(s:upper()) do
			table.insert(out, utf8.char(c))
		end
		return table.concat(out, " ")
	end

	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Text = wordmark(brandName),
		TextColor3 = colors.text,
		TextSize = 16,
		FontFace = Theme.Font.Bold,
		Parent = titlebar,
	})

	-- Right cluster holds a collapsible search field followed by the window
	-- buttons; the horizontal list keeps them packed against the right edge.
	local rightCluster = Create("Frame", {
		Name = "RightCluster",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -18, 0.5, 0),
		Size = UDim2.fromOffset(0, M.titlebar),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Parent = titlebar,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 14),
		}),
	})

	-- search field — hidden until the search button is clicked. A CanvasGroup so
	-- its width can slide open while every child fades in together; ClipsDescendants
	-- keeps the icon/box from spilling out while it's narrower than its content.
	local SEARCH_W = 180
	local searchField = Create("CanvasGroup", {
		Name = "Search",
		Visible = false,
		Size = UDim2.fromOffset(SEARCH_W, 30),
		BackgroundColor3 = colors.control,
		ClipsDescendants = true,
		LayoutOrder = 1,
		Parent = rightCluster,
	}, {
		Create.corner(M.controlRadius),
		Create.stroke(colors.border),
		Create.padding(0, 10),
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 8),
		}),
	})
	local searchIcon = Icons.new("search", 14, colors.text_dim)
	searchIcon.LayoutOrder = 1;
	(searchIcon :: any).Parent = searchField
	local searchBox = Create("TextBox", {
		Name = "Box",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -22, 1, 0),
		Text = "",
		PlaceholderText = "Search",
		PlaceholderColor3 = colors.text_dim,
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		ClearTextOnFocus = false,
		LayoutOrder = 2,
		Parent = searchField,
	})

	local winButtons = Create("Frame", {
		Name = "WinButtons",
		Size = UDim2.fromOffset(0, M.titlebar),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		Parent = rightCluster,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 15),
		}),
	})

	local winBtns: { [string]: TextButton } = {}
	for i, name in { "search", "min", "max", "close" } do
		local btn = Create("TextButton", {
			Name = name,
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(16, 16),
			Text = "",
			LayoutOrder = i,
			Parent = winButtons,
		})
		local icon = Icons.new(name, 16, colors.text_muted)
		icon.AnchorPoint = Vector2.new(0.5, 0.5)
		icon.Position = UDim2.fromScale(0.5, 0.5);
		(icon :: any).Parent = btn

		local over = name == "close" and colors.danger or colors.text
		btn.MouseEnter:Connect(function()
			Tween.play(icon, Tween.Fast, { ImageColor3 = over })
		end)
		btn.MouseLeave:Connect(function()
			Tween.play(icon, Tween.Fast, { ImageColor3 = colors.text_muted })
		end)
		winBtns[name] = btn
	end

	-- ── body: sidebar + content ─────────────────────────────────────────────
	local body = Create("Frame", {
		Name = "Body",
		Position = UDim2.fromOffset(0, M.titlebar),
		Size = UDim2.new(1, 0, 1, -(M.titlebar + M.statusbar)),
		BackgroundColor3 = colors.bg,
		Parent = main,
	})

	local sidebar = Create("Frame", {
		Name = "Sidebar",
		Size = UDim2.new(0, M.sidebar, 1, 0),
		BackgroundColor3 = colors.chrome,
		Parent = body,
	}, {
		Create("Frame", {
			Name = "Border",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.fromScale(1, 0),
			Size = UDim2.new(0, 1, 1, 0),
			BackgroundColor3 = colors.border_soft,
			BorderSizePixel = 0,
		}),
	})

	-- Nav buttons live in their own frame so the sidebar's UIListLayout never
